package com.spinplayer.app;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.DocumentsContract;import android.media.MediaMetadataRetriever;import java.util.*;import java.io.*;import org.json.*;
public final class MusicFolders {
 static JSONArray roots(Context c){try{return new JSONArray(c.getSharedPreferences("spin",0).getString("musicFolders","[]"));}catch(Exception e){return new JSONArray();}}
 static void save(Context c,JSONArray a){c.getSharedPreferences("spin",0).edit().putString("musicFolders",a.toString()).apply();}
 static String identity(Uri u){try{return u.getAuthority()+":"+DocumentsContract.getDocumentId(u);}catch(Exception e){return u.toString();}}
 static String identity(Context c,Uri u){try{if("com.android.externalstorage.documents".equals(u.getAuthority())){String id=DocumentsContract.getDocumentId(u);if(id.startsWith("primary:"))return "storage:"+id;}Uri media=u;if("com.android.providers.media.documents".equals(u.getAuthority())){String id=DocumentsContract.getDocumentId(u);if(id.startsWith("audio:"))media=android.content.ContentUris.withAppendedId(android.provider.MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,Long.parseLong(id.substring(6)));}if("media".equals(media.getAuthority()))try(Cursor q=c.getContentResolver().query(media,new String[]{android.provider.MediaStore.MediaColumns.RELATIVE_PATH,android.provider.MediaStore.MediaColumns.DISPLAY_NAME},null,null,null)){if(q!=null&&q.moveToFirst()&&q.getString(0)!=null)return "storage:primary:"+q.getString(0)+q.getString(1);}}catch(Exception ignored){}return identity(u);}
 public static void add(Context c,Uri tree)throws Exception{JSONArray a=roots(c);for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getString("uri").equals(tree.toString()))return;String name=DocumentsContract.getTreeDocumentId(tree);Uri doc=DocumentsContract.buildDocumentUriUsingTree(tree,name);try(Cursor q=c.getContentResolver().query(doc,new String[]{DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(q!=null&&q.moveToFirst())name=q.getString(0);}a.put(new JSONObject().put("uri",tree.toString()).put("name",name));save(c,a);}
 public static void remove(Context c,String raw)throws Exception{JSONArray roots=roots(c),kept=new JSONArray();for(int i=0;i<roots.length();i++)if(!roots.getJSONObject(i).optString("uri").equals(raw))kept.put(roots.getJSONObject(i));save(c,kept);JSONArray lib=MusicLibrary.load(c),out=new JSONArray();for(int i=0;i<lib.length();i++){JSONObject t=lib.getJSONObject(i);JSONArray owners=t.optJSONArray("folderRoots");if(owners==null){out.put(t);continue;}JSONArray rest=new JSONArray();for(int k=0;k<owners.length();k++)if(!raw.equals(owners.optString(k)))rest.put(owners.optString(k));t.put("folderRoots",rest);if(rest.length()>0||!t.optBoolean("folderOwned"))out.put(t);}MusicLibrary.save(c,out);/* Keep persisted grants: existing manually imported songs may share this tree permission. */}
 public static JSONObject scan(Context c)throws Exception{int added=0,failed=0;JSONArray roots=roots(c),lib=MusicLibrary.load(c);Map<String,JSONObject> known=new HashMap<>();for(int i=0;i<lib.length();i++){JSONObject t=lib.getJSONObject(i);known.put(identity(c,Uri.parse(t.optString("uri"))),t);}for(int i=0;i<roots.length();i++){JSONObject root=roots.getJSONObject(i);Uri tree=Uri.parse(root.getString("uri"));ArrayDeque<String> dirs=new ArrayDeque<>();Set<String> visited=new HashSet<>();Map<String,String> paths=new HashMap<>();paths.put(DocumentsContract.getTreeDocumentId(tree),"");dirs.add(DocumentsContract.getTreeDocumentId(tree));int found=0;Set<String> seenFiles=new HashSet<>();boolean complete=true;try{while(!dirs.isEmpty()){String dir=dirs.removeFirst();if(!visited.add(dir))continue;Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,dir);try(Cursor q=c.getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE},null,null,null)){if(q==null)throw new IOException("FolderQuery");while(q.moveToNext()){String id=q.getString(0),name=q.getString(1),mime=q.getString(2);if(DocumentsContract.Document.MIME_TYPE_DIR.equals(mime)){dirs.add(id);paths.put(id,paths.get(dir)+name+"/");continue;}if(!(mime!=null&&mime.startsWith("audio/"))&&!name.toLowerCase(Locale.ROOT).matches(".*\\.(mp3|m4a|mp4|flac|ogg|opus|wav|aac|webm)$"))continue;Uri file=DocumentsContract.buildDocumentUriUsingTree(tree,id);String key=identity(c,file);seenFiles.add(key);JSONObject t=known.get(key);if(t==null){try{t=read(c,file,name);t.put("folderOwned",true);known.put(key,t);lib.put(t);added++;}catch(Exception e){failed++;continue;}}if(!t.has("year")||!t.has("albumArtist")){MediaMetadataRetriever meta=new MediaMetadataRetriever();try{meta.setDataSource(c,file);if(!t.has("year"))t.put("year",value(meta,MediaMetadataRetriever.METADATA_KEY_YEAR,""));if(!t.has("albumArtist"))t.put("albumArtist",value(meta,MediaMetadataRetriever.METADATA_KEY_ALBUMARTIST,""));}catch(Exception ignored){}finally{try{meta.release();}catch(Exception ignored){}}}JSONArray owners=t.optJSONArray("folderRoots");if(owners==null)owners=new JSONArray();boolean has=false;for(int k=0;k<owners.length();k++)if(tree.toString().equals(owners.optString(k)))has=true;if(!has)owners.put(tree.toString());t.put("folderRoots",owners);JSONObject locations=t.optJSONObject("folderPaths");if(locations==null)locations=new JSONObject();locations.put(tree.toString(),paths.get(dir));t.put("folderPaths",locations);found++;}}}}catch(Exception e){complete=false;failed++;}if(complete){JSONArray kept=new JSONArray();for(int k=0;k<lib.length();k++){JSONObject song=lib.getJSONObject(k);JSONArray owners=song.optJSONArray("folderRoots");if(owners!=null&&!seenFiles.contains(identity(c,Uri.parse(song.optString("uri"))))){JSONArray rest=new JSONArray();for(int n=0;n<owners.length();n++)if(!tree.toString().equals(owners.optString(n)))rest.put(owners.optString(n));song.put("folderRoots",rest);if(song.optBoolean("folderOwned")&&rest.length()==0)continue;}kept.put(song);}lib=kept;}root.put("count",found).put("error",complete?"":"Не все файлы прочитаны. Проверь доступ к папке.").put("lastScan",System.currentTimeMillis());}MusicLibrary.save(c,lib);save(c,roots);return new JSONObject().put("added",added).put("failed",failed).put("folders",roots);}
 static JSONObject read(Context c,Uri u,String filename)throws Exception{MediaMetadataRetriever m=new MediaMetadataRetriever();try{m.setDataSource(c,u);int id=MusicLibrary.id(identity(c,u));JSONObject t=new JSONObject().put("id",id).put("name",value(m,MediaMetadataRetriever.METADATA_KEY_TITLE,filename.replaceFirst("\\.[^.]+$",""))).put("artist",value(m,MediaMetadataRetriever.METADATA_KEY_ARTIST,"Неизвестный исполнитель")).put("album",value(m,MediaMetadataRetriever.METADATA_KEY_ALBUM,"Без альбома")).put("duration",Long.parseLong(value(m,MediaMetadataRetriever.METADATA_KEY_DURATION,"0"))/1000.0).put("number",value(m,MediaMetadataRetriever.METADATA_KEY_CD_TRACK_NUMBER,"0").split("/")[0]).put("year",value(m,MediaMetadataRetriever.METADATA_KEY_YEAR,"")).put("albumArtist",value(m,MediaMetadataRetriever.METADATA_KEY_ALBUMARTIST,"")).put("uri",u.toString()).put("native",true).put("cover","app-cover.svg");byte[] art=m.getEmbeddedPicture();if(art!=null&&art.length<5000000){File d=new File(c.getFilesDir(),"art");d.mkdirs();try(FileOutputStream o=new FileOutputStream(new File(d,id+".jpg"))){o.write(art);}t.put("cover","art/"+id+".jpg");}return t;}finally{m.release();}}
 static String value(MediaMetadataRetriever m,int key,String fallback){String s=m.extractMetadata(key);return s==null||s.trim().isEmpty()?fallback:s;}
}
